import pytest
from PIL import Image as PILImage
from requests.exceptions import HTTPError, InvalidSchema, RequestException

from saleor.product import ProductMediaTypes, tasks
from saleor.product.models import ProductMedia


def make_media(product, **kwargs):
    defaults = dict(
        product=product,
        type=ProductMediaTypes.IMAGE,
        external_url="http://example.com/img.png",
        oembed_data="{}",
    )
    defaults.update(kwargs)
    return ProductMedia.objects.create(**defaults)


def valid_png_bytes():
